                {/* --- PARAMS TAB --- */}
                {activeTab === 'params' && (
                    <div className="space-y-4">
                        <fieldset className="border border-gray-600 p-2 rounded bg-gray-800/50">
                            <legend className="text-xs font-bold text-blue-400 px-1">Зазор и Отступы</legend>
